const sqlite3 = require('sqlite3').verbose();

// Leggi le impostazioni di quiete dal database
const settings = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.all(
    `SELECT chiave, valore FROM system_settings 
     WHERE chiave IN ('orario_quiete_inizio', 'orario_quiete_fine', 'giorni_esclusi')`,
    [],
    function(err, rows) {
      db.close();
      if (err) reject(err);
      else resolve(rows);
    }
  );
});

const cfg = {};
for (const row of settings) {
  cfg[row.chiave] = row.valore;
}

const ora_quiete_inizio = cfg.orario_quiete_inizio || '21:00';
const ora_quiete_fine = cfg.orario_quiete_fine || '07:30';
const giorni_esclusi = (cfg.giorni_esclusi || 'domenica').split(',').map(g => g.trim());

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const giornoSettimana = ['domenica','lunedi','martedi','mercoledi','giovedi','venerdi','sabato'][now.getDay()];
const oraCorrente = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;

// Controlla se siamo in orario di quiete
const isGiornoEscluso = giorni_esclusi.includes(giornoSettimana);
const isOrarioQuiete = oraCorrente >= ora_quiete_inizio || oraCorrente < ora_quiete_fine;

const puoiInviare = !isGiornoEscluso && !isOrarioQuiete;

return [{
  json: {
    puo_inviare: puoiInviare,
    ora_corrente: oraCorrente,
    giorno: giornoSettimana
  }
}];

const sqlite3 = require('sqlite3').verbose();

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const nowISO = now.toISOString().slice(0, 19).replace('T', ' ');

const tasks = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.all(
    `SELECT * FROM task 
     WHERE stato = 'aperto'
     AND (scadenza IS NOT NULL AND scadenza <= ?)
     AND (snooze_until IS NULL OR snooze_until <= ?)
     AND (next_followup_at IS NULL OR next_followup_at <= ?)
     ORDER BY scadenza ASC
     LIMIT 10`,
    [nowISO, nowISO, nowISO],
    function(err, rows) {
      db.close();
      if (err) reject(err);
      else resolve(rows);
    }
  );
});

return [{
  json: {
    tasks: tasks,
    count: tasks.length
  }
}];

const http = require('http');
const sqlite3 = require('sqlite3').verbose();

const tasks = $input.first().json.tasks;
const destinatario = '+393495931632'; // sostituisci con il tuo numero

const toniSollecito = [
  (t) => `Ciao Cesare, ti ricordo che hai un task in scadenza: "${t.descrizione}". Riesci a occupartene oggi?`,
  (t) => `Cesare, il task "${t.descrizione}" è ancora aperto e scaduto. Vuoi occupartene adesso o preferisci posticiparlo?`,
  (t) => `Attenzione Cesare: il task "${t.descrizione}" è in arretrato da un po'. Ti conviene pianificare uno slot per completarlo.`,
  (t) => `⚠️ Cesare, il task "${t.descrizione}" è rimasto aperto troppo a lungo. Richede la tua attenzione urgente.`
];

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const nowISO = now.toISOString().slice(0, 19).replace('T', ' ');

// Calcola prossimo followup (3 ore da adesso)
const nextFollowup = new Date(now.getTime() + 3 * 60 * 60 * 1000);
const nextFollowupISO = nextFollowup.toISOString().slice(0, 19).replace('T', ' ');

for (const task of tasks) {
  const idx = Math.min(task.reminder_count, toniSollecito.length - 1);
  const testo = toniSollecito[idx](task);

  // Invia messaggio Signal
  await new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      message: testo,
      number: '+393517872627',
      recipients: [destinatario]
    });
    const options = {
      hostname: 'segretario_signal_cli',
      port: 8080,
      path: '/v2/send',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data));
    });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });

  // Aggiorna il task nel database
  await new Promise((resolve, reject) => {
    const db = new sqlite3.Database('/data/segretario.db');
    db.run(
      `UPDATE task SET 
        reminder_count = reminder_count + 1,
        ultimo_sollecito = ?,
        next_followup_at = ?,
        updated_at = ?
       WHERE id = ?`,
      [nowISO, nextFollowupISO, nowISO, task.id],
      function(err) {
        db.close();
        if (err) reject(err);
        else resolve();
      }
    );
  });
}

return [{
  json: {
    solleciti_inviati: tasks.length,
    stato: 'completato'
  }
}];
